const CRATES_API = "https://crates.io/api/v1/crates";

/**
 * Cargo Version Check Extension
 *
 * Intercepts `cargo add` bash commands and direct Cargo.toml edits/writes.
 * For each dependency being added, queries crates.io for the latest version.
 * If a newer version exists, silently rewrites the tool call to use it.
 */
export default function (pi) {
  pi.on("tool_call", async (event, ctx) => {
    // --- bash: catch `cargo add <crate>@<ver>` ---
    if (event.toolName === "bash") {
      const input = event.input as any;
      const command = input?.command ?? "";
      await handleCargoAdd(command, input, ctx);
      return;
    }

    // --- edit / write: catch direct Cargo.toml modifications ---
    if (event.toolName === "edit" || event.toolName === "write") {
      const input = event.input as any;
      const path = input?.path ?? "";

      let content = input?.newText ?? input?.content ?? "";
      if (typeof content !== "string") content = JSON.stringify(content);

      if (!isCargoTomlLike(path)) return;

      const updated = await checkAndPatchDependencies(content, event.toolName === "write");
      if (updated) {
        if (event.toolName === "edit") {
          input.newText = updated;
        } else {
          input.content = updated;
        }
      }
    }
  });

  pi.on("session_start", async (_event, ctx) => {
    ctx.ui.notify("cargo-version-check: enabled", "info");
  });
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function isCargoTomlLike(path: string): boolean {
  const base = path.split("/").pop()?.toLowerCase() ?? "";
  return base === "cargo.toml" || /^Cargo\.toml\./.test(base);
}

/**
 * Handle `cargo add` commands.  Rewrites the @version suffix to the
 * latest crates.io release when a newer version exists.
 */
async function handleCargoAdd(command: string, input: any, ctx: any) {
  if (!command.includes("cargo")) return;

  // Split into tokens roughly matching shell behaviour (handle quotes).
  const tokens = tokenizeShell(command);
  const addIdx = tokens.findIndex((t) => t === "add");
  if (addIdx < 0 || addIdx + 1 >= tokens.length) return;

  const rawPkg = tokens[addIdx + 1];
  // Skip flags starting with -
  if (rawPkg.startsWith("-")) return;

  const parsed = parseCargoPkg(rawPkg);
  if (!parsed) return;

  const latest = await fetchLatestVersion(parsed.name);
  if (!latest) return;

  // If explicit version and it's stale, rewrite.
  if (parsed.version && compareSemver(parsed.version, latest) < 0) {
    const newPkg = parsed.version === "*" ? parsed.name : `${parsed.name}@${latest}`;
    // Replace the first occurrence of rawPkg in the command safely.
    input.command = command.replace(rawPkg, newPkg);
    ctx.ui.notify(
      `Updated ${parsed.name}: ${parsed.version} → ${latest}`,
      "info"
    );
  } else if (!parsed.version) {
    // Bare package name – default to latest.
    const newPkg = `${parsed.name}@${latest}`;
    input.command = command.replace(rawPkg, newPkg);
    ctx.ui.notify(
      `Added latest ${parsed.name}@${latest}`,
      "info"
    );
  }
}

/**
 * Parse "crate@1.2.3" → { name: "crate", version: "1.2.3" }
 */
function parseCargoPkg(raw: string): { name: string; version?: string } | null {
  const idx = raw.indexOf("@");
  if (idx < 0) return raw.length > 0 ? { name: raw } : null;
  const name = raw.slice(0, idx);
  const version = raw.slice(idx + 1);
  if (!name || version === "") return null;
  return { name, version };
}

/**
 * Fetch the latest stable version from crates.io.
 */
async function fetchLatestVersion(pkg: string): Promise<string | null> {
  try {
    const res = await fetch(`${CRATES_API}/${encodeURIComponent(pkg)}`, {
      signal: new AbortController().signal,
    });
    if (!res.ok) return null;
    const data = (await res.json()) as { max_version?: string };
    return data.max_version ?? null;
  } catch {
    return null;
  }
}

/**
 * Compare two semver strings loosely. Returns -1, 0, or 1.
 * Strips leading "^", "~", "=", "v" etc.
 */
function compareSemver(a: string, b: string): number {
  const aParts = sanitizeVer(a).split(".").map(Number);
  const bParts = sanitizeVer(b).split(".").map(Number);

  for (let i = 0; i < Math.max(aParts.length, bParts.length); i++) {
    const av = aParts[i] ?? 0;
    const bv = bParts[i] ?? 0;
    if (av === bv) continue;
    return av < bv ? -1 : 1;
  }
  return 0;
}

function sanitizeVer(v: string): string {
  return v.replace(/^[~^>=v<]+/, "");
}

/**
 * Patch all dependency lines in a Cargo.toml snippet.
 * For `write` (full file): scans [dependencies] / [dev-dependencies] / etc.
 * For `edit` (partial text): checks the diff block directly.
 */
async function checkAndPatchDependencies(
  content: string,
  fullFile: boolean
): Promise<string | null> {
  const lines = content.split("\n");
  let patched = false;
  let inDepsSection = false;

  // We need async inside map, so use a for loop.
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (fullFile) {
      // Track which sections we're inside (only for full-file writes).
      if (/^\s*\[.*dependencies.*\]/i.test(line)) {
        inDepsSection = true;
      } else if (/^\s*\[/.test(line)) {
        inDepsSection = false;
      }
      if (!inDepsSection) continue;
    }

    const depLine = parseDepLine(line);
    if (!depLine) continue;

    const latest = await fetchLatestVersion(depLine.name);
    if (!latest) continue;

    const curVer = depLine.version ?? "0.0.0";
    if (compareSemver(curVer, latest) < 0) {
      lines[i] = patchLineVersion(line, latest);
      patched = true;
    }
  }

  return patched ? lines.join("\n") : null;
}

/**
 * Parse a single Cargo.toml dependency line.
 * Handles:
 *   serde = "1.0.150"
 *   serde = { version = "1.0", features = [...] }
 *   serde = "1.0.150"          # with extra inline table fields
 */
function parseDepLine(line: string): { name: string; version?: string } | null {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("[")) return null;

