  const eqIdx = trimmed.indexOf("=");
  if (eqIdx < 0) return null;

  const name = trimmed.slice(0, eqIdx).trim().replace(/"/g, "");
  const rest = trimmed.slice(eqIdx + 1).trim();

  // Skip path / git deps
  if (rest.includes("path =") || rest.includes("git =")) return null;

  // Bare name: `serde` (no value after =) → already at latest when cargo resolves
  if (!rest || rest === "\"\"") {
    return { name };
  }

  // Inline table: { version = "1.0" ... }
  if (rest.startsWith("{")) {
    const m = rest.match(/version\s*=\s*"([^"]+)"/);
    if (m) return { name, version: m[1] };
    return null;
  }

  // Quoted version: "1.0.150"
  const m2 = rest.match(/^"([^"]+)"/);
  if (m2) return { name, version: m2[1] };

  return null;
}

/**
 * Replace the version in a dependency line with `newVersion`.
 */
function patchLineVersion(line: string, newVersion: string): string {
  // Inline table: version = "x.y.z"
  let result = line.replace(
    /(version\s*=\s*)"([^"]+)"/,
    `$1"${newVersion}"`
  );

  // Quoted version (first "= "value"):
  if (!result.includes(`"${newVersion}"`)) {
    const eqPos = result.indexOf("=");
    if (eqPos >= 0) {
      const before = result.slice(0, eqPos + 1).trim();
      const after = result.slice(eqPos + 1).trim();
      const m = after.match(/^"?([^"]*)"?/);
      if (m) {
        result = `${before} "${newVersion}"${after.slice(m[0].length)}`;
      }
    }
  }

  return result;
}

/**
 * Minimal shell tokenizer – good enough for cargo add commands.
 */
function tokenizeShell(str: string): string[] {
  const tokens: string[] = [];
  let cur = "";
  let inSingle = false;
  let inDouble = false;

  for (const ch of str) {
    if (ch === "'" && !inDouble) { inSingle = !inSingle; continue; }
    if (ch === '"' && !inSingle) { inDouble = !inDouble; continue; }
    if (ch === " " && !inSingle && !inDouble) {
      if (cur) { tokens.push(cur); cur = ""; }
      continue;
    }
