const CRATES_API = "https://crates.io/api/v1/crates";
const CHANGELOG_GITHUB =
  "https://api.github.com/repos/TBA/TBA/releases/latest";

/**
 * Cargo Version Guard Extension
 *
 * Intercepts `cargo add` and direct Cargo.toml writes/edits that pin a
 * dependency version.  When a newer version exists on crates.io it **blocks
 * the tool call** and tells the agent:
 *   - which version is available
 *   - to research changelog / API changes before upgrading
 */
export default function (pi) {
  pi.on("tool_call", async (event, ctx) => {
    // --- bash: `cargo add <pkg>@<ver>` or sed that touches Cargo.toml ---
    if (event.toolName === "bash") {
      const input = event.input as any;
      const command = input?.command ?? "";

      // Check for `cargo add` in compound commands (&& etc.)
      const result = await handleCargoAdd(command);
      if (result) return { block: true, reason: result };

      // Also catch sed / direct Cargo.toml edits via bash (less common but
      // possible when the agent uses sed instead of edit tool).
      if (command.includes("Cargo.toml")) {
        const sedResult = await handleBashCargoToml(command);
        if (sedResult) return { block: true, reason: sedResult };
      }
    }

    // --- write / edit: direct Cargo.toml modifications ---
    if (event.toolName === "edit" || event.toolName === "write") {
      const input = event.input as any;
      const path = input?.path ?? "";
      let content = input?.newText ?? input?.content ?? "";
      if (typeof content !== "string") content = JSON.stringify(content);

      if (!isCargoTomlLike(path)) return;

      const staleDeps = await findStaleDepsInContent(
        content,
        event.toolName === "write"
      );
      if (staleDeps.length > 0) {
        return { block: true, reason: buildBlockMessage(staleDeps) };
      }
    }
  });

  pi.on("session_start", async (_event, ctx) => {
    ctx.ui.notify("cargo-version-guard enabled", "info");
  });
}

// ------------------------------------------------------------------ */
//  Core logic                                                            */
// ------------------------------------------------------------------ */

/** Returns a block message if cargo add uses an outdated version, else null. */
async function handleCargoAdd(command: string): Promise<string | null> {
  if (!command.includes("cargo")) return null;

  // Tokenize respecting simple shell rules.
  const tokens = tokenizeShell(command);
  const addIdx = tokens.findIndex((t) => t === "add");
  if (addIdx < 0 || addIdx + 1 >= tokens.length) return null;

  const rawPkg = tokens[addIdx + 1];
  if (rawPkg.startsWith("-")) return null;

  const parsed = parseCargoPkg(rawPkg);
  if (!parsed) return null;

  // Skip if no version is pinned (cargo will grab latest anyway).
  if (!parsed.version || parsed.version === "*") return null;

  const latest = await fetchLatestVersion(parsed.name);
  if (!latest) return null;

  if (compareSemver(parsed.version, latest) < 0) {
    return buildSingleBlockMessage(parsed.name, parsed.version, latest);
  }
  return null;
}

/**
 * Rough heuristic: if a bash command patches Cargo.toml with a version
 * number, try to extract it.  Fails gracefully.
 */
async function handleBashCargoToml(command: string): Promise<string | null> {
  // Look for patterns like sed 's/old/new/' Cargo.toml where new contains a
  // semver.  Best-effort; we don't want to block non-version edits.
  const versionInPatch = extractVersionFromCommand(command);
  if (!versionInPatch) return null;

  const latest = await fetchLatestVersion(versionInPatch.name);
  if (!latest) return null;

  if (compareSemver(versionInPatch.version, latest) < 0) {
    return buildSingleBlockMessage(
      versionInPatch.name,
      versionInPatch.version,
      latest
    );
  }
  return null;
}

// ------------------------------------------------------------------ */
//  Cargo.toml content scanning                                          */
// ------------------------------------------------------------------ */

async function findStaleDepsInContent(
  content: string,
  fullFile: boolean
): Promise<Array<{ name: string; current: string; latest: string }>> {
  const lines = content.split("\n");
  const stale: Array<{ name: string; current: string; latest: string }> = [];
  let inDepsSection = false;

  for (const line of lines) {
    if (fullFile) {
      if (/^\s*\[.*dependencies.*\]/i.test(line)) {
        inDepsSection = true;
      } else if (/^\s*\[/.test(line)) {
        inDepsSection = false;
      }
      if (!inDepsSection) continue;
    }

    const dep = parseDepLine(line);
    if (!dep || !dep.version) continue;

    const latest = await fetchLatestVersion(dep.name);
    if (!latest) continue;

    if (compareSemver(dep.version, latest) < 0) {
      stale.push({ name: dep.name, current: dep.version, latest });
    }
  }

  return stale;
}

// ------------------------------------------------------------------ */
//  Message builders                                                     */
// ------------------------------------------------------------------ */

function buildSingleBlockMessage(
  name: string,
  current: string,
  latest: string
): string {
  return `⚠️ The crate "${name}" has a newer version available. You tried to use ${current} but the latest on crates.io is ${latest}.

IMPORTANT: Before proceeding with `cargo add`, you MUST:
1. Update your command to use version ${latest} instead of ${current}
2. Check the changelog or release notes for breaking changes, renamed exports, deprecated functions, or new required dependencies  (e.g. visit https://crates.io/crates/${name}#history)
3. Verify the API surface you need still exists and hasn't changed its signature

Only after verifying compatibility should you re-run `cargo add ${name}@${latest}`.

Do not proceed with the old version — it may cause compilation errors or subtle bugs from using outdated / deprecated APIs.`;
}

function buildBlockMessage(staleDeps: Array<{ name: string; current: string; latest: string }>): string {
  const crateList = staleDeps.map(
    (d) => `- ${d.name}: ${d.current} → ${d.latest}`
  ).join("\n");

  return `⚠️ The following crates have newer versions available:

${crateList}

Before writing Cargo.toml, you MUST:
1. Update each entry to its latest version listed above
2. Research the changelog / release notes for each crate at https://crates.io/crates/<name>#history
3. Look for breaking changes, renamed types, deprecated functions, or changed trait bounds
4. Adjust your source code if the new API differs from what you expected

Do not proceed with stale versions — they risk compile errors and hard-to-debug issues from deprecated/removed APIs.`;
}

// ------------------------------------------------------------------ */
//  Helpers                                                              */
// ------------------------------------------------------------------ */

function isCargoTomlLike(path: string): boolean {
  const base = path.split("/").pop()?.toLowerCase() ?? "";
  return base === "cargo.toml" || /^Cargo\.toml\./.test(base);
}

function parseCargoPkg(raw: string): { name: string; version?: string } | null {
  const idx = raw.indexOf("@");
  if (idx < 0) return raw.length > 0 ? { name: raw } : null;
  const name = raw.slice(0, idx);
  const version = raw.slice(idx + 1);
  if (!name || version === "") return null;
  return { name, version };
}

async function fetchLatestVersion(pkg: string): Promise<string | null> {
  try {
    const res = await fetch(`${CRATES_API}/${encodeURIComponent(pkg)}`, {
      signal: new AbortController().signal,
    });
    if (!res.ok) return null;
    const data = (await res.json()) as { max_version?: string };
    return data.max_version ?? null;
  } catch {
    return null;
  }
}

function compareSemver(a: string, b: string): number {
  const aParts = sanitizeVer(a).split(".").map(Number);
  const bParts = sanitizeVer(b).split(".").map(Number);
  for (let i = 0; i < Math.max(aParts.length, bParts.length); i++) {
    const av = aParts[i] ?? 0;
    const bv = bParts[i] ?? 0;
    if (av === bv) continue;
    return av < bv ? -1 : 1;
  }
  return 0;
}

function sanitizeVer(v: string): string {
  return v.replace(/^[~^>=v<]+/, "");
}

function parseDepLine(line: string): { name: string; version?: string } | null {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("["))
    return null;

  const eqIdx = trimmed.indexOf("=");
  if (eqIdx < 0) return null;

  const name = trimmed.slice(0, eqIdx).trim().replace(/"/g, "");
  const rest = trimmed.slice(eqIdx + 1).trim();

  // Skip path / git deps
  if (rest.includes("path =") || rest.includes("git =")) return null;
  if (!rest || rest === "\"\"") return { name };

  if (rest.startsWith("{")) {
    const m = rest.match(/version\s*=\s*"([^"]+)"/);
    if (m) return { name, version: m[1] };
    return null;
  }

  const m2 = rest.match(/^"([^"]+)"/);
  if (m2) return { name, version: m2[1] };

  return null;
}

function extractVersionFromCommand(cmd: string):
  | { name: string; version: string }
  | null {
  // Heuristic: look for a semver-like pattern near "Cargo.toml".
  const match = cmd.match(
    /(?:serde|tokio|reqwest|clap|anyhow|thiserror|rayon|regex|syn|quote|proc-macro2)@?(\d+\.\d+(?:\.\d+)?)?/i
  );
  if (!match || !match[1]) return null;
  return { name: match[0].replace(/\d+\.\d+(\.\d+)?/, "").at(0) || "", version: match[1] };
}

function tokenizeShell(str: string): string[] {
  const tokens: string[] = [];
  let cur = "";
  let inSingle = false;
  let inDouble = false;

  for (const ch of str) {
    if (ch === "'" && !inDouble) { inSingle = !inSingle; continue; }
    if (ch === '"' && !inSingle) { inDouble = !inDouble; continue; }
    if (ch === " " && !inSingle && !inDouble) {
      if (cur) { tokens.push(cur); cur = ""; }
      continue;
    }
    cur += ch;
  }
  if (cur) tokens.push(cur);
  return tokens;
}

const CRATES_API = "https://crates.io/api/v1/crates";

/**
 * Cargo Version Guard Extension
 *
 * Intercepts `cargo add <pkg>@<ver>` and direct Cargo.toml edits.
 * When a pinned version is behind the crates.io release, it **blocks** the
 * tool call and returns:
 *   - the stale vs. latest versions side-by-side
 *   - a link to the crate's CHANGELOG or repo so the agent can research
 *     API deltas before using the newer release
 *   - an explicit instruction NOT to proceed until it has verified
 *     compatibility
 */
export default function (pi) {
  pi.on("tool_call", async (event, ctx) => {
    // ─────────── bash: cargo add ───────────
    if (event.toolName === "bash") {
      const input = event.input as any;
      const command = (input?.command ?? "").replace(/^#!/, "");

      const result = await handleCargoAdd(command);
      if (result) return { block: true, reason: result };
    }

    // ─────────── edit / write: Cargo.toml ───────────
    if (event.toolName === "edit" || event.toolName === "write") {
