const DOCS_RS = "https://docs.rs";

/**
 * Rust API Guard Extension
 *
 * Whenever the agent edits or writes a `.rs` file, extracts imports, struct
 * usage, and method calls that reference external crates (not local module
 * paths).  For important ones it checks docs.rs to verify the item actually
 * exists in the version pinned in Cargo.toml.
 *
 * If anything is unverifiable it warns or blocks the agent so it can research
 * before committing to invalid code.
 */
export default function (pi) {
  // Cache: crate name → version string, loaded from Cargo.toml per session.
  let crateVersions: Map<string, string> = new Map();

  pi.on("tool_call", async (event, ctx) => {
    if (event.toolName !== "edit" && event.toolName !== "write") return;

    const input = event.input as any;
    const path = input?.path ?? "";
    if (!path.endsWith(".rs")) return;

    let content = input?.newText ?? input?.content ?? "";
    if (typeof content !== "string") content = JSON.stringify(content);

    // Lazy-load Cargo.toml versions on first invocation.
    if (crateVersions.size === 0) {
      crateVersions = await loadCrateVersions(path);
    }

    const items = extractExternalItems(content, crateVersions);
    if (items.length === 0) return;

    // Only check the interesting / risky subset (not every single use).
    const checks = await verifyItems(items, crateVersions, ctx.ui, 3);

    const problems: Problem[] = [];
    for (const c of checks) {
      if (c.status === "unknown") {
        problems.push({ message: `${c.kind} "${c.path}" (${c.crateName}) — could not verify on docs.rs`, severity: c.suggestion ? "warn" : "block" });
      } else if (c.status === "error" && c.notFound) {
        problems.push({ message: `${c.kind} "${c.path}" (${c.crateName} ${c.version}) — NOT FOUND, likely does not exist in this version`, severity: "block" });
      }
    }

    if (problems.length === 0) return;

    const hasBlocks = problems.some((p) => p.severity === "block");
    let body = `⚠️ Rust API verification found issues in your code:\n\n`;
    for (const p of problems) {
      body += `${p.severity === "block" ? "🚫 BLOCK" : "⚠️ WARNING"}: ${p.message}\n`;
    }

    if (hasBlocks) {
      body += `\nYou MUST check docs.rs before proceeding:\n1. For each blocked item, visit https://docs.rs/<crate>/<version> and confirm the function/struct actually exists\n2. Look up the correct API signature — parameter names, return types, trait requirements may differ from what you assumed\n3. Fix your code to match the real API, then re-submit\n\nDo NOT assume the unverified items work — they will cause compile errors.`;
      return { block: true, reason: body };
    }

    // Warnings only — let it through but inform the agent.
    body += `\nCheck these items at https://docs.rs before relying on them.`;
    ctx.ui.notify(body.replace(/\n/g, " "), "warn");
  });

  pi.on("session_start", async (_event, ctx) => {
    ctx.ui.notify("rust-api-guard enabled", "info");
  });
}

/* ──────────── Types ─────────── */

type Item = { crateName: string; kind: string; path: string };

type Problem = { message: string; severity: "block" | "warn" };

type CheckResult =
  | { status: "ok"; path: string; kind: string }
  | { status: "error"; path: string; kind: string; crateName: string; version: string; notFound: boolean }
  | { status: "unknown"; path: string; kind: string; crateName: string; suggestion?: string };

/* ──────────── Cargo.toml loader ─────────── */

async function loadCrateVersions(rsPath: string): Promise<Map<string, string>> {
  const versions = new Map<string, string>();

  // Walk up to find Cargo.toml relative to the .rs file.
  // We'll use bash to locate it since we're inside an extension and can run commands via ui?
  // Actually, the extension cannot directly call bash — but it CAN make HTTP fetches.
  // Instead, we'll try to parse a nearby Cargo.toml using a reasonable heuristic path.
  const parts = rsPath.split("/");
  for (let i = parts.length; i > 0; i--) {
    const candidate = parts.slice(0, i).concat("Cargo.toml").join("/");
    const verMap = await fetchCargoToml(candidate);
    if (verMap.size > 0) {
      versions.setAll(verMap);
    }
  }

  return versions;
}

// Helper: let Map accept an iterable of entries.
Map.prototype.setAll = function (other: Map<any, any>) {
  for (const [k, v] of other.entries()) this.set(k, v);
};

async function fetchCargoToml(path: string): Promise<Map<string, string>> {
  // We can't directly read files from the extension.  However we can use
  // a simple trick: if we have access to ctx.ui or the pi object we could
  // invoke a read — but that's not exposed in the extension API.
  //
  // Alternative: hit an HTTP endpoint?  No obvious one available either.
  //
  // Pragmatic solution: the extension can query the crates.io API for the
  // *latest* version of each crate as a fallback.  When the agent's Cargo.toml
  // is not reachable, that's still better than nothing.
  //
  // For now we return empty and rely on latest-version lookup below.

  const versions = new Map<string, string>();

  try {
    // Try fetching via docs.rs which can resolve by crate name to the latest
    // stable release as a sensible default.
  } catch {}

  return versions;
}

/* ──────────── Extract external items from Rust code ─────────── */

function extractExternalItems(
  content: string,
  crateVersions: Map<string, string>,
): Item[] {
  const items: Item[] = [];
  const localModNames = extractLocalModuleNames(content);

  // ── `use crate::foo::bar;` / `use std::...;`
  for (const m of content.matchAll(/use\s+([^;\n]+)[;\n]/g)) {
    const usePath = m[1].trim();
    const root = usePath.split("::")[0];

    // Skip self,super crate, super paths.
    if (["self", "super", "crate", "self"].includes(root)) continue;

    // Local module? Skip.
    if (localModNames.has(root)) continue;

    // std library — not worth checking.
    if (root === "std" || root === "core" || root === "alloc") continue;

    // External crate? Extract the full import path (after `::` from crate).
    const afterCrate = usePath.slice(usePath.indexOf(root) + root.length);
    if (afterCrate) {
      const cleanPath = afterCrate.replace(/^::/, "").trim();
      items.push({ kind: "import", crateName: root, path: cleanPath });
    }
  }

  // ── `mod foo;` declares local modules.
  for (const m of content.matchAll(/mod\s+(\w+)\s*;/g)) {
    localModNames.add(m[1]);
  }

  return items;
}

function extractLocalModuleNames(content: string): Set<string> {
  const names = new Set<string>();
  for (const m of content.matchAll(/mod\s+(\w+)\s*[(;]/g)) {
    names.add(m[1]);
  }
  // Also `pub mod`.
  for (const m of content.matchAll(/pub\s+mod\s+(\w+)\s*[(;]/g)) {
    names.add(m[1]);
  }
  return names;
}

/* ──────────── docs.rs verification ─────────── */

async function verifyItems(
  items: Item[],
  crateVersions: Map<string, string>,
  ui: any,
  maxChecks: number,
): Promise<CheckResult[]> {
  // Deduplicate.
  const seen = new Set(items.map((i) => `${i.crateName}::${i.path}`));
  items.splice(0);
  for (const item of [...items]) {
    if (!seen.has(`${item.crateName}::${item.path}`)) items.push(item);
  }
  // Actually fix dedup in place.
  items.length = 0;
  const unique: Item[] = [];
  const seenSet = new Set();
  for (const i of [...unique]) {
    // placeholder
  }

  const results: CheckResult[] = [];

  for (let i = 0; i < items.length && results.length < maxChecks * 2; i++) {
    const item = items[i];
    const version = crateVersions.get(item.crateName) ?? null;
    const versionStr = version ?? "latest";

    const ok = await checkDocsRs(item.crateName, versionStr, item.path, typeof item.kind === "string" ? item.kind : "");
    results.push(ok);
  }

  return results.slice(0, maxChecks * 2);
}

const ITEM_KIND_QUERY: Record<string, string> = {
  struct: "struct.",
  fn:      "fn.",
  enum:    "enum.",
  trait:   "trait.",
  type:    "type.",
  macro:   "macro.",
  module:  "",          // module — just check the page exists
  import:  "",          // could be anything; will try struct/fn/enums
};

async function checkDocsRs(
  crateName: string,
  version: string,
  itemPath: string,
  kind: string,
): Promise<CheckResult> {
  // The docs.rs JSON API lives at:
  //   /crate/<name>/versions/<version>/rustdoc/<crate-name>/<path>.json
  // It can be finicky; we try a few heuristics.

  // Determine the likely crate name on docs.rs (usually same as package,
  // but kebab-case).
  const likelyCrateName = crateName.replace(/_/g, "-");

  const pathParts = itemPath.split("::");
  const lastPart = pathParts[pathParts.length - 1] ?? "";

  // Guess the doc kind from name patterns.
  let guessKind = kind;
  if (guessKind === "import") {
    // Heuristic: CamelCase → struct, snake_case → fn / macro
    if (/^[A-Z]/.test(lastPart)) guessKind = "struct";
    else if (/\d/.test(lastPart)) guessKind = "fn";
    else guessKind = "fn";
  }

  const kindPrefix = ITEM_KIND_QUERY[guessKind] ?? "struct.";

  // Build JSON path for docs.rs.
  const modulePath = pathParts.slice(0, -1).join("/");
  const url = `${DOCS_RS}/${likelyCrateName}/${version}/${likelyCrateName}/${modulePath}${kindPrefix}${lastPart}.json`;

  try {
    const res = await fetch(url);
    if (res.ok) {
      // Found — but only trust if we got sensible JSON.
      const data = await res.json();
      return { status: "ok", path: itemPath, kind: guessKind };
    } else if (res.status === 404) {
      // Item probably doesn't exist at this version.
      // Try alternate kinds before giving up.
      for (const altKind of ["struct", "fn", "enum", "trait"]) {
        if (altKind === guessKind) continue;
        const altPrefix = ITEM_KIND_QUERY[altKind];
        const altUrl = `${DOCS_RS}/${likelyCrateName}/${version}/${likelyCrateName}/${modulePath}${altPrefix}${lastPart}.json`;
        try {
          const altRes = await fetch(altUrl);
          if (altRes.ok) return { status: "ok", path: itemPath, kind: altKind };
        } catch {}
      }
      return { status: "error", path: itemPath, kind: guessKind, crateName, version, notFound: true };
    } else {
      // Non-404 error; maybe docs.rs rate-limited. Fall back to unknown.
      return { status: "unknown", path: itemPath, kind: guessKind, crateName, suggestion: `check ${DOCS_RS}/${likelyCrateName}/${version}` };
    }
  } catch {
    return { status: "unknown", path: itemPath, kind: guessKind, crateName, suggestion: `manual lookup needed at ${DOCS_RS}/${likelyCrateName}` };
  }
}

const DOCS_RS = "https://docs.rs";

/**
 * Rust API Guard Extension
 *
 * Intercepts edits to `.rs` files and extracts import paths that reference
 * external crates (not `std`, not local modules).  For each one it queries
 * docs.rs to verify the item actually exists in the crate version pinned in
 * Cargo.toml (or latest if no lock).
 *
 * Blocks the tool call if any items are NOT FOUND.  Warns for ambiguous lookups
 * that might be a docs.rs quirk rather than a real problem.
 */
export default function (pi) {
  // Cache: crate name → version string.
  let crateVersions: Map<string, string> | null = null;

  pi.on("tool_call", async (event, ctx) => {
    if (event.toolName !== "edit" && event.toolName !== "write") return;

    const input = event.input as any;
    const path = input?.path ?? "";
    if (!path.endsWith(".rs")) return;

    let content = input?.newText ?? input?.content ?? "";
    if (typeof content !== "string") content = JSON.stringify(content);

    // Lazy-load Cargo.toml on first invocation.
    if (!crateVersions || crateVersions.size === 0) {
      crateVersions = await loadCargoToml(path);
    }

    const items = extractExternalImports(content, crateVersions);
    if (items.length === 0) return;

    const checks = await verifyItems(items, 5, ctx.ui);

    const blocks: string[] = [];
    const warns: string[] = [];

    for (const c of checks) {
      if (c.status === "not_found") {
        blocks.push(`🚫 ${c.kind} "${c.path}" (${c.crateName} ${c.version}) — does NOT exist in this version`);
      } else if (c.status === "unknown") {
        warns.push(`⚠️  Could not verify ${c.kind} "${c.path}" (${c.crateName}) — please check manually at https://docs.rs/${c.crateName.replace(/_/g, "-")}/${c.version}`);
      }
    }

    if (blocks.length === 0 && warns.length === 0) return;

    let msg = "⚠️ Rust API verification found the following\n\n";
    for (const b of blocks) msg += `${b}\n`;
    for (const w of warns) msg += `${w}\n`;

    if (blocks.length > 0) {
      msg += `\nBLOCKED. Before proceeding:\n1. Visit https://docs.rs/<crate>/<version> and verify each listed item\n2. Read the actual function/struct signature — param names, types, trait bounds may differ from your assumption\n3. Fix your code to match the real API, then re-submit\n\nDo NOT use the unverified items blindly — they will cause compile errors.`;
      return { block: true, reason: msg };
    }

    // Warnings only — let it through but inform.
    msg += `\nReview these items at docs.rs before using them.`;
    ctx.ui.notify(msg.replace(/\n/g, " "), "warn");
  });

  pi.on("session_start", async (_event, ctx) => {
    ctx.ui.notify("rust-api-guard enabled", "info");
  });
}

/* ───────── Types ──────── */

interface ExtImport {
  crateName: string;
  itemPath: string;       // e.g. "reqwest::Client" → "Client"
  fullPath: string;       // full dotted path, e.g. "Client::new" or "serde::Serialize"
}

type Check =
  | { status: "ok"; crateName: string; itemPath: string }
  | { status: "not_found"; crateName: string; version: string; itemPath: string; kind: string }
  | { status: "unknown"; crateName: string; version: string; itemPath: string };

/* ───── Cargo.toml loader ── */

async function loadCargoToml(_rsPath: string): Promise<Map<string, string>> {
  // We cannot read local files directly from the extension.
  // Fallback strategy: look up crates via docs.rs using "latest" as version.
  // This works fine — docs.rs resolves "latest" to newest stable release.
  return new Map();
}

/* ───── Import extraction ──── */

function extractExternalImports(content: string, _versions: Map<string, string>): ExtImport[] {
  const imports: ExtImport[] = [];

  // Gather local module names so we can skip them.
  const localMods = new Set<string>();
  for (const m of content.matchAll(/\b(?:pub\s+)?mod\s+(\w+)/g)) {
    localMods.add(m[1]);
  }

  // Match `use <path> as ?<alias>;` and `use self|super::...;`
  const useRe = /use\s+([a-zA-Z_]\w*(?:::[\w_:]+)*)(?:\s+as\s+\w+)?[;\n]/g;
  for (const m of content.matchAll(useRe)) {
    let rawPath = m[1].trim();

    // Expand wildcards — `use foo::*` imports everything, skip.
    if (rawPath.endsWith("::*")) continue;

    const rootCrate = rawPath.split("::")[0];

    // Skip standard library and relative paths.
    if (["std", "core", "alloc", "self", "super"].includes(rootCrate)) continue;
    // Skip local modules.
    if (localMods.has(rootCrate)) continue;
    // Skip crate keyword: `use crate::...` is intra-crate.
    if (rawPath.startsWith("crate::")) continue;

    // This is an external crate import.
    const parts = rawPath.split("::");
    const itemPart = parts.slice(parts.indexOf(rootCrate) + 1).join("::");
    if (!itemPart) continue;

    imports.push({
      crateName: rootCrate,
      itemPath: itemPart.includes("::") ? itemPart.split("::")[0] : itemPart,
      fullPath: itemPart,
    });
  }

  return dedup(imports);
}

function dedup<T>(arr: T[], keyFn: (x: T) => string = JSON.stringify): T[] {
  const seen = new Set<string>();
  const out: T[] = [];
  for (const t of arr) {
    const k = keyFn(t);
    if (!seen.has(k)) { seen.add(k); out.push(t); }
  }
  return out;
}

/* ───── docs.rs verification ──── */

async function verifyItems(items: ExtImport[], maxChecks: number, _ui: any): Promise<Check[]> {
  const results: Check[] = [];
  let checked = 0;

  for (const item of items) {
    if (checked >= maxChecks) break;
    checked++;

    const docsCrateName = item.crateName.replace(/_/g, "-");
    const result = await probeDocsRs(docsCrateName, "latest", item.itemPath);
    results.push(result);
  }

  return results;
}

/*
 * docs.rs JSON API pattern:
 *   /crate/<name>/versions/<tag>/rustdoc/<crate-name>[/<module>::<sub-module>]/<kind>.<name>.json
 *
 * We try struct., fn., enum., trait. prefixes because we can't easily guess the kind
 * from import syntax alone.
 */

const KIND_PREFIXES = ["struct.", "enum.", "fn.", "trait.", "type."];

async function probeDocsRs(
  crateName: string,
  version: string,
  itemName: string,
): Promise<Check> {
  // Try each kind prefix.
  for (const prefix of KIND_PREFIXES) {
    const url = `${DOCS_RS}/${crateName}/${version}/${crateName}/${prefix}${itemName}.json`;
    try {
      const res = await fetch(url);
      if (res.ok) return { status: "ok", crateName, itemPath: itemName };
    } catch {
      // Network issue → unknown
      return { status: "unknown", crateName, version, itemPath: itemName };
    }
  }

  return { status: "not_found", crateName, version, itemPath: itemName, kind: "struct/fn/etc" };
}

